create table if not exists public.user_profiles(user_id uuid primary key references auth.users(id) on delete cascade,email text not null,role text not null default 'user' check(role in('user','admin')),created_at timestamptz default now());
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,provider text not null default 'paystack',provider_subscription_code text,plan_code text not null,status text not null default 'pending' check(status in('pending','active','past_due','cancelled','suspended','expired','comped')),amount integer not null default 1000,currency text not null default 'USD',interval text not null default 'monthly',current_period_start timestamptz,current_period_end timestamptz,cancel_at_period_end boolean default false,admin_note text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subscription_id uuid references public.subscriptions(id) on delete set null,provider text not null default 'paystack',provider_reference text not null unique,provider_transaction_id text,amount integer not null,currency text not null default 'USD',status text not null default 'pending' check(status in('pending','success','failed','reversed','refunded')),paid_at timestamptz,raw_event jsonb default '{}'::jsonb,created_at timestamptz default now());
create index if not exists subscriptions_user_status_idx on public.subscriptions(user_id,status);
create index if not exists payments_user_created_idx on public.payments(user_id,created_at desc);
alter table public.user_profiles enable row level security; alter table public.subscriptions enable row level security; alter table public.payments enable row level security;
create policy "read own profile" on public.user_profiles for select using(auth.uid()=user_id);
create policy "read own subscriptions" on public.subscriptions for select using(auth.uid()=user_id);
create policy "read own payments" on public.payments for select using(auth.uid()=user_id);
insert into public.user_profiles(user_id,email) select id,coalesce(email,'') from auth.users on conflict(user_id) do update set email=excluded.email;
create or replace function public.handle_cyberlab_signup() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.user_profiles(user_id,email) values(new.id,coalesce(new.email,'')) on conflict(user_id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists cyberlab_user_signup on auth.users;
create trigger cyberlab_user_signup after insert on auth.users for each row execute procedure public.handle_cyberlab_signup();
